begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.uid(n integer)returns uuid language sql immutable as $$select ('19150000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data)
select pg_temp.uid(n),'authenticated','authenticated','engage-s191-'||n||'@veyocast.test','test',now(),now(),now(),'{}','{}'from generate_series(1,3)n;
insert into public.profiles(id,display_name)select pg_temp.uid(n),'Engage '||n from generate_series(1,3)n;
insert into public.tenants(id,name,slug,screen_limit)values(pg_temp.uid(10),'Engage A','engage-s191-a',5),(pg_temp.uid(11),'Engage B','engage-s191-b',5);
insert into public.tenant_settings(tenant_id)values(pg_temp.uid(10)),(pg_temp.uid(11));
insert into public.tenant_memberships(tenant_id,user_id,role)values(pg_temp.uid(10),pg_temp.uid(1),'tenant_owner'),(pg_temp.uid(11),pg_temp.uid(2),'tenant_owner'),(pg_temp.uid(10),pg_temp.uid(3),'tenant_viewer');
insert into public.tenant_feature_flags(tenant_id,flag_key,enabled,rollout_reason)values(pg_temp.uid(10),'engage',true,'S191 local proof'),(pg_temp.uid(11),'engage',true,'S191 local proof');
create temporary table results(name text primary key,value jsonb);grant all on results to authenticated;
create function pg_temp.payload(title text default 'Clubkeuze')returns jsonb language sql as $$select jsonb_build_object('kind','poll','title',title,'question','Welke optie kies je?','resultVisibility','after_close','startsAt',null,'endsAt',null,'options',jsonb_build_array(jsonb_build_object('label','Optie A'),jsonb_build_object('label','Optie B')))$$;
create function pg_temp.save(key integer,revision bigint default 0,title text default 'Clubkeuze',campaign uuid default null)returns jsonb language sql as $$select public.save_engage_campaign_v2(pg_temp.uid(10),campaign,revision,pg_temp.payload(title),pg_temp.uid(key))$$;
set local role authenticated;select set_config('request.jwt.claim.sub',pg_temp.uid(1)::text,true);
insert into results values('create',pg_temp.save(100));
select is((select value->>'outcome'from results where name='create'),'created','real draft command creates the campaign');
select is((select revision from public.engage_campaigns),0::bigint,'created draft starts at revision zero');
select is((select count(*)from public.engage_options),2::bigint,'both ordered options are persisted');
select is(pg_temp.save(100),(select value from results where name='create'),'same request replays its actual acknowledgement');
select is((select count(*)from public.engage_campaigns),1::bigint,'create retry does not duplicate campaigns');
select throws_ok($$select pg_temp.save(100,0,'Changed retry')$$,'23505',null,'reusing a key with changed input fails closed');
insert into results values('edit',pg_temp.save(101,0,'Nieuwe clubkeuze',(select id from public.engage_campaigns)));
select is((select value->>'outcome'from results where name='edit'),'applied','draft editing is acknowledged');
select is((select revision from public.engage_campaigns),1::bigint,'metadata edit advances revision once');
select is((select title from public.engage_campaigns),'Nieuwe clubkeuze','readback returns saved title');
insert into results values('conflict',pg_temp.save(102,0,'Stale title',(select id from public.engage_campaigns)));
select is((select value->>'outcome'from results where name='conflict'),'conflict','second session cannot overwrite a changed draft');
select is((select(value->>'actualRevision')::bigint from results where name='conflict'),1::bigint,'conflict contains actual revision');
select is((select title from public.engage_campaigns),'Nieuwe clubkeuze','stale input cannot replace metadata');
select is((select count(*)from public.engage_options),2::bigint,'stale command does not delete options');
select is(pg_temp.save(102,0,'Stale title',(select id from public.engage_campaigns)),(select value from results where name='conflict'),'conflict retry replays the same result');
select throws_ok($$select public.save_engage_campaign_v2(pg_temp.uid(10),null,0,pg_temp.payload()||'{"unexpected":true}',pg_temp.uid(103))$$,'22023',null,'unknown fields cannot bypass the typed boundary');
select throws_ok($$select public.save_engage_campaign_v2(pg_temp.uid(10),null,0,jsonb_set(pg_temp.payload(),'{options}','[{"label":"A","id":"spoofed"},{"label":"B"}]'),pg_temp.uid(104))$$,'22023',null,'option identities remain server controlled');
select throws_ok($$select public.save_engage_campaign_v2(pg_temp.uid(10),null,0,jsonb_set(pg_temp.payload(),'{title}',to_jsonb(repeat('x',33000))),pg_temp.uid(105))$$,'22023',null,'oversized payload is rejected before authoring');
select throws_ok($$select public.save_engage_campaign_v2(pg_temp.uid(10),null,0,jsonb_set(pg_temp.payload(),'{options}','[{"label":"Only one"}]'),pg_temp.uid(106))$$,'23514',null,'incomplete options roll back the entire command');
select is((select count(*)from public.engage_campaigns),1::bigint,'invalid command leaves no partial campaign');
select lives_ok($$select public.transition_engage_campaign_v1(pg_temp.uid(10),(select id from public.engage_campaigns),'live')$$,'complete draft transitions through actual lifecycle command');
select is((select revision from public.engage_campaigns),2::bigint,'lifecycle also invalidates old draft revision');
reset role;
insert into public.engage_votes(tenant_id,campaign_id,option_id,identity_hash,network_hash)
select pg_temp.uid(10),campaign.id,option.id,repeat('a',64),repeat('b',64)from public.engage_campaigns campaign join public.engage_options option on option.campaign_id=campaign.id order by option.sort_order limit 1;
set local role authenticated;
select throws_ok($$select public.save_engage_campaign_v1(pg_temp.uid(10),(select id from public.engage_campaigns),'poll','Unsafe edit','Would delete live choices','live',null,null,'[{"label":"New A"},{"label":"New B"}]')$$,'42501',null,'legacy path also rejects editing a live campaign');
select throws_ok($$select pg_temp.save(107,2,'Unsafe edit',(select id from public.engage_campaigns))$$,'42501',null,'current revision never authorizes mutable live options');
select is((select count(*)from public.engage_options),2::bigint,'both live options survive rejected editing');
reset role;select is((select count(*)from public.engage_votes),1::bigint,'live vote survives both rejected paths');
set local role authenticated;select set_config('request.jwt.claim.sub',pg_temp.uid(3)::text,true);
select throws_ok($$select pg_temp.save(108)$$,'42501',null,'viewer cannot create or edit campaigns');
select set_config('request.jwt.claim.sub',pg_temp.uid(2)::text,true);
select is((select count(*)from public.engage_campaigns),0::bigint,'tenant B cannot read tenant A campaign');
select throws_ok($$select pg_temp.save(109)$$,'42501',null,'tenant B cannot write tenant A');
select set_config('request.jwt.claim.sub',pg_temp.uid(1)::text,true);
reset role;update public.tenant_feature_flags set enabled=false where tenant_id=pg_temp.uid(10)and flag_key='engage';
set local role authenticated;
select throws_ok($$select pg_temp.save(110)$$,'42501',null,'disabled feature rejects command even for owner');
reset role;
select ok(not has_function_privilege('anon','public.save_engage_campaign_v2(uuid,uuid,bigint,jsonb,uuid)','execute'),'anonymous cannot execute draft command');
select ok(not has_function_privilege('service_role','public.save_engage_campaign_v2(uuid,uuid,bigint,jsonb,uuid)','execute'),'service role cannot forge author command');
select * from finish();
rollback;
